import { readFileSync } from 'node:fs';

const PASSAGES = JSON.parse(readFileSync(new URL('./passages.json', import.meta.url), 'utf8'));
const X = (key, context) => ({ passage: (context ? `(${context})\n\n` : '') + PASSAGES[key].passage, passageSource: PASSAGES[key].passageSource });
const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `english.${id}`, topic: `english.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({
  id: `english.${id}`, topic: `english.${topic}`, kind: 'mcq', prompt,
  options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra,
});
const order = (id, topic, prompt, items, explain, extra = {}) => ({ id: `english.${id}`, topic: `english.${topic}`, kind: 'order', prompt, items, labels: null, explain, ...extra });
const written = (id, topic, prompt, hints, model, extra = {}) => ({ id: `english.${id}`, topic: `english.${topic}`, kind: 'written', prompt, hints, model, words: [60, 250], ...extra });
